What is the value of `nums[1]` when the `printf` runs?

```c
void change(int a[], int size) {
    a[1] = 50;
    size = 0;
}

int main(void) {
    int nums[4], n = 4, i;
    for (i = 0; i < n; i++) {
        nums[i] = i * 10;
    }
    change(nums, n);
    printf("%d %d\n", nums[1], n);
    return 0;
}
```

